import{_ as a,o,c as i,a2 as n}from"./chunks/framework.BN2sqjC1.js";const p=JSON.parse('{"title":"Il primo vault","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/primo-vault.md","filePath":"user-guide/primo-vault.md"}'),t={name:"user-guide/primo-vault.md"};function r(l,e,s,c,d,m){return o(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="il-primo-vault" tabindex="-1">Il primo vault <a class="header-anchor" href="#il-primo-vault" aria-label="Permalink to &quot;Il primo vault&quot;">​</a></h1><p>Un <strong>vault</strong> è una cartella sul vostro computer che contiene le note. Potete avere più vault, ma ogni vault è un mondo a sé: link, backlink, grafo, ricerca e segnalibri non attraversano i vault.</p><h2 id="aprire-un-vault" tabindex="-1">Aprire un vault <a class="header-anchor" href="#aprire-un-vault" aria-label="Permalink to &quot;Aprire un vault&quot;">​</a></h2><p><em>Apri cartella come vault</em> nella schermata iniziale; i vault recenti sono elencati sotto. Si possono aprire anche vault creati con Obsidian: le note, gli allegati e i file <code>.canvas</code> restano com&#39;erano.</p><h2 id="l-interfaccia" tabindex="-1">L&#39;interfaccia <a class="header-anchor" href="#l-interfaccia" aria-label="Permalink to &quot;L&#39;interfaccia&quot;">​</a></h2><ul><li><strong>Intestazione:</strong> in alto a sinistra i pulsanti per mostrare/nascondere la barra sinistra e per cercare nel vault; a destra la palette comandi, il passaggio <strong>chiaro/scuro</strong> e il pulsante della barra destra. Il nome del vault è al centro.</li><li><strong>Azioni rapide</strong> (colonna di icone a sinistra): nuova cartella, nota, lavagna, disegno, base, <em>separatore</em> (inserisce una riga <code>---</code> nella nota), esporta in PDF, esporta come immagine. In fondo: le <strong>impostazioni</strong> e il vostro <strong>account</strong> (le iniziali se avete fatto l&#39;accesso al cloud, altrimenti il pulsante <em>Accedi</em>).</li><li><strong>Barra laterale sinistra:</strong> schede <em>File</em> (albero delle cartelle, nuova nota/cartella, ordinamento; clic destro, o tasto Menu / <code>Maiusc+F10</code>, per rinominare, spostare nel cestino, copiare il percorso, aggiungere ai segnalibri) e <em>Struttura</em> (i titoli della nota aperta). La ricerca si apre dalla lente in alto e compare come terza scheda finché la usate. In fondo: il <strong>vault aperto</strong> con il numero di note; un clic mostra i vault recenti e permette di cambiare vault senza tornare alla schermata iniziale (<code>Cambia vault</code> nella palette).</li><li><strong>Area centrale:</strong> schede (tab) e pannelli divisibili (<code>Mod+\\</code> a destra, <code>Mod+Maiusc+\\</code> in basso). Si trascinano le schede tra i pannelli. Il clic destro su una scheda permette di <strong>bloccarla</strong> (non si chiude per errore e la navigazione si apre in una scheda nuova) e di chiudere le schede a destra, a sinistra, le altre o tutte (quelle bloccate restano).</li><li><strong>Barra laterale destra</strong> (schede a icona): <em>Proprietà</em>, <em>Tag</em>, <em>Link</em> (link in uscita, backlink e segnalibri del vault), <em>Slide</em> (<a href="./presentazioni.html">presentazioni</a>) e <em>Statistiche</em> (date, autore, versioni, con chi è condivisa, parole e titoli della nota). In fondo: lo <strong>stato del vault</strong> (indicizzazione, sincronizzazione, inviti in attesa, permesso sul vault condiviso, aggiornamenti); con la barra chiusa lo stesso blocco passa nell&#39;intestazione.</li><li><strong>Barra di stato</strong> (facoltativa, spenta per default): accendetela da <em>Impostazioni → Aspetto</em> o con il comando <em>Mostra/nascondi barra di stato</em>. È una riga sottile sotto l&#39;area centrale con parole e caratteri della nota (quelli selezionati, se c&#39;è una selezione), riga e colonna del cursore e la modalità, che un clic fa passare da Live a Sorgente a Lettura. Su disegni, lavagne e basi mostra solo il tipo di file; durante una presentazione si nasconde.</li><li><strong>Palette comandi</strong> (<code>Mod+P</code>): ogni azione dell&#39;app, con la sua scorciatoia.</li></ul><h2 id="prime-note" tabindex="-1">Prime note <a class="header-anchor" href="#prime-note" aria-label="Permalink to &quot;Prime note&quot;">​</a></h2><ol><li><code>Mod+N</code> crea una nota; il titolo è il nome del file.</li><li>Scrivete: il salvataggio è automatico e <strong>atomico</strong> (non si ottengono file a metà anche se il computer si spegne).</li><li>Se modificate un file con un altro programma, l&#39;app se ne accorge; non sovrascrive mai una modifica esterna senza avvisarvi.</li><li><code>Mod+O</code> apre il <strong>selettore rapido</strong>: digitate parte del nome per aprire una nota (o un&#39;applicazione, una lavagna, una base, un disegno), o per crearla se non esiste.</li></ol><p>Cartelle e note si possono spostare e rinominare dall&#39;albero: i link che puntano alla nota vengono aggiornati (l&#39;app mostra quanti link in quante note verranno modificati prima di procedere).</p><h3 id="nomi-dei-file-ed-estensioni" tabindex="-1">Nomi dei file ed estensioni <a class="header-anchor" href="#nomi-dei-file-ed-estensioni" aria-label="Permalink to &quot;Nomi dei file ed estensioni&quot;">​</a></h3><p>L&#39;albero dei file, le schede e le intestazioni mostrano i nomi <strong>senza estensione</strong> per tutto ciò che l&#39;app apre in una scheda: note (<code>.md</code>), presentazioni (<code>.marp</code>), disegni (<code>.excalidraw</code>), lavagne (<code>.canvas</code>), basi (<code>.base</code>), applicazioni (<code>.webapp</code>), immagini, PDF, audio e video. <code>Piano.canvas</code> compare come «Piano»; nell&#39;albero un&#39;icona dice di che tipo è, e il suggerimento mostra il percorso. Due file con lo stesso nome e tipi diversi (una nota <code>Piano</code> e una lavagna <code>Piano</code>) restano vicini nell&#39;elenco e si distinguono solo dall&#39;icona. I file che l&#39;app non apre da sé (per esempio <code>.docx</code>, <code>.zip</code>, <code>LICENSE</code>) si mostrano con il <strong>nome intero</strong>, estensione compresa, e si aprono con il programma del sistema.</p><p><strong>Rinominare</strong> (<code>F2</code>, o il menu della riga, o il comando <em>Rinomina nota</em>) mostra il nome senza estensione e <strong>non permette di cambiarla</strong>: l&#39;estensione originale viene rimessa da sola, quindi un disegno resta un disegno. Se scrivete anche l&#39;estensione uguale a quella del file (<code>Diagramma.excalidraw</code>), non viene raddoppiata; se scrivete un&#39;altra estensione (<code>Foo.txt</code> su una nota), diventa parte del nome (<code>Foo.txt.md</code>). Gli spazi ai lati del nome si tolgono; un nome vuoto o uguale a quello di prima non fa nulla. Per cartelle e file non supportati il nome è intero, come prima. <strong>Per cambiare davvero l&#39;estensione di un file supportato bisogna usare il file system</strong>: l&#39;app non lo permette. Il testo che i link inseriscono non cambia (un link a una presentazione resta <code>[[Review.marp]]</code>).</p>',12)])])}const g=a(t,[["render",r]]);export{p as __pageData,g as default};
